import { PhoneNumberCard, PlayerUpgrades, RarityTier } from '../types/game';

// Base income per second generated by a single phone number depending on its rarity tier
export const BASE_NUMBER_INCOME: Record<RarityTier, number> = {
  common: 2,        // 2 ₽/сек
  uncommon: 12,     // 12 ₽/сек
  rare: 65,         // 65 ₽/сек
  epic: 320,        // 320 ₽/сек
  legendary: 1800,  // 1 800 ₽/сек
  mythic: 15000,    // 15 000 ₽/сек
};

// Calculate income generated by a single phone number card with upgrades applied
export function getCardIncomePerSec(card: PhoneNumberCard, upgrades: PlayerUpgrades): number {
  const base = BASE_NUMBER_INCOME[card.rarity] || 2;
  const favBonus = card.isFavorite ? 1.25 : 1.0;
  const rentMultiplier = 1 + (upgrades.numberRentMultiplierLevel || 0) * 0.05;
  const roamingMultiplier = 1 + (upgrades.roamingLevel || 0) * 0.08;
  const prestigeMultiplier = 1 + (upgrades.prestigeLevel || 0) * 0.50;

  return Math.max(1, Math.round(base * favBonus * rentMultiplier * roamingMultiplier * prestigeMultiplier));
}

// Calculate total steady passive income per second from user's entire phone number collection
export function calculateCoinsPerSec(
  collection: PhoneNumberCard[],
  upgrades: PlayerUpgrades
): number {
  if (!collection || collection.length === 0) {
    // If collection is empty, base pool level provides a modest starting drip
    const pool = (upgrades.simPoolLevel || 0) * 15;
    return pool;
  }

  let totalBase = 0;
  for (const card of collection) {
    const cardBase = BASE_NUMBER_INCOME[card.rarity] || 2;
    const favBonus = card.isFavorite ? 1.25 : 1.0;
    totalBase += cardBase * favBonus;
  }

  // Add digital SIM pool bonus
  totalBase += (upgrades.simPoolLevel || 0) * 35;

  const rentMultiplier = 1 + (upgrades.numberRentMultiplierLevel || 0) * 0.05;
  const roamingMultiplier = 1 + (upgrades.roamingLevel || 0) * 0.08;
  const prestigeMultiplier = 1 + (upgrades.prestigeLevel || 0) * 0.50;

  return Math.round(totalBase * rentMultiplier * roamingMultiplier * prestigeMultiplier);
}

// Calculate offline earnings based on elapsed time (capped at 24 hours)
export function calculateOfflineEarnings(
  lastTimestamp: number,
  coinsPerSec: number
): { secondsOffline: number; earned: number } {
  if (!lastTimestamp || coinsPerSec <= 0) return { secondsOffline: 0, earned: 0 };
  const now = Date.now();
  const elapsedSeconds = Math.max(0, Math.floor((now - lastTimestamp) / 1000));

  // Cap offline farm at 24 hours (86,400 seconds)
  const cappedSeconds = Math.min(86400, elapsedSeconds);
  const earned = cappedSeconds * coinsPerSec;

  return {
    secondsOffline: elapsedSeconds,
    earned,
  };
}

